import{$n as qE,Mn as ji,Ot as WD,Qn as qD,ln as dI,lt as ST,ot as Rh,un as dh,vn as fh,wn as hl}from"./chunk-CrWQ3QIY.js";import"./chunk-DEheUMgV.js";import"./chunk-CahX9C6Q.js";import{t as _}from"./chunk-B2x17KqA.js";import{n as l,t as N}from"./chunk-DI4XcNrl.js";var b=(a,n)=>n.pregunta;function q(a,n){if(a&1&&(ji(0,`ec-accordion-item`,5)(1,`p`,6),ST(2),hl()()),a&2){let e=n.$implicit;dh(`title`,e.pregunta),dI(2),Rh(e.respuesta)}}var f=class a{preguntas=[{pregunta:`¿Cuánto cuesta publicar una vacante?`,respuesta:`Nada. Publicar, recibir la terna, revisar fichas verificadas y mover candidatos por el proceso no tiene costo. Se cobra una sola vez, al contratar, y las condiciones están en el convenio que firmas antes de publicar.`},{pregunta:`¿Esto sustituye la entrevista técnica?`,respuesta:`No, y sería sospechoso que alguien lo prometiera. Lo que sustituye es la parte de la entrevista que se dedica a averiguar si lo que dice el CV es cierto: eso ya viene comprobado, con el trabajo entregado y el nombre de quien lo evaluó. La entrevista queda para lo que solo tú puedes valorar, que es el encaje con tu equipo.`},{pregunta:`¿De dónde sale el porcentaje de encaje?`,respuesta:`De cuatro factores con su peso declarado: cobertura de las competencias excluyentes de tu vacante, evidencia evaluada por rúbrica, encaje de banda salarial y disponibilidad frente a tu fecha de cierre. El desglose viaja con cada candidato, así que puedes discutirlo en lugar de creértelo.`},{pregunta:`¿El candidato sabe que vi su perfil?`,respuesta:`Sí, y lo decimos antes de que abras la ficha. Cada consulta queda registrada con tu empresa, tu nombre y qué evidencia se consultó, y el candidato la ve en su panel. Es la contrapartida de que él haya aceptado ser visible: la transparencia va en las dos direcciones.`},{pregunta:`¿Puedo pedir que una persona revise una terna?`,respuesta:`Sí. Ordenar candidatos es una decisión automatizada y toda decisión automatizada de esta plataforma tiene su vía de revisión humana, tanto para ti como para el candidato. La solicitud entra en una cola con plazo comprometido y quien la revisa puede confirmarla o revertirla.`},{pregunta:`¿Qué pasa si la contratación no funciona?`,respuesta:`El convenio incluye un plazo de garantía pactado con el equipo comercial: dentro de ese plazo no asumes el costo de la contratación. Fuera de él se aplica lo que hayas firmado, que leíste cláusula por cláusula antes de aceptarlo.`},{pregunta:`¿Ven otras empresas mis vacantes o mis candidatos?`,respuesta:`No. Cada empresa ve exclusivamente sus vacantes, sus procesos y las fichas de los candidatos que participan en ellos. El aislamiento entre empresas es un requisito de diseño de la plataforma, no una configuración que alguien pueda desactivar por error.`}];static ɵfac=function(e){return new(e||a)};static ɵcmp=qE({type:a,selectors:[[`ec-b2b-preguntas`]],decls:7,vars:1,consts:[[1,`faq`],[1,`faq__interior`],[`title`,`Preguntas frecuentes`,`description`,`Las dos primeras son las que de verdad hay que resolver antes de decidir: cuánto cuesta y qué trabajo te ahorra.`],[1,`faq__lista`],[3,`headingLevel`],[3,`title`],[1,`faq__respuesta`]],template:function(e,y){e&1&&(ji(0,`section`,0)(1,`div`,1),fh(2,`ec-section-header`,2),ji(3,`div`,3)(4,`ec-accordion`,4),qD(5,q,3,2,`ec-accordion-item`,5,b),hl()()()()),e&2&&(dI(4),dh(`headingLevel`,3),dI(),WD(y.preguntas))},dependencies:[l,N,_],styles:[`[_nghost-%COMP%]{display:block}.faq[_ngcontent-%COMP%]{padding-block:var(--%NS%ec-space-16)}.faq__interior[_ngcontent-%COMP%]{inline-size:100%;max-inline-size:var(--%NS%ec-container-prose);margin-inline:auto;padding-inline:var(--%NS%ec-space-5)}.faq__lista[_ngcontent-%COMP%]{margin-block-start:var(--%NS%ec-space-8)}.faq__respuesta[_ngcontent-%COMP%]{font-size:var(--%NS%ec-text-body);line-height:var(--%NS%ec-leading-body);font-family:var(--%NS%ec-font-ui);font-weight:var(--%NS%ec-weight-regular);color:var(--%NS%ec-text-secondary)}`]})};export{f as B2bPreguntasComponent};